<!--vbase-->
<template>
  <template v-if="is_module_on">
    <f-btn
      @click="
        showSyncDataPopup = true;
        initForm();
      "
      id="po_sync_data_btn"
      class="q-pl-sm q-pr-sm q-mr-sm"
    >
      <Icon icon="mdi:sync" width="20" height="20" />
      <q-tooltip>{{ $t('sync_data') }}</q-tooltip>
    </f-btn>

    <q-dialog v-model="showSyncDataPopup" persistent>
      <q-card style="width: 700px; max-width: 50vw">
        <q-card flat class="popup-background">
          <q-toolbar class="pr-0">
            <q-toolbar-title>
              <span class="secondary-c-text text-h6 text-weight-bold">
                {{ $t('sync_data') }}
              </span>
            </q-toolbar-title>

            <f-btn
              flat
              round
              dense
              appearance="tertiary"
              icon="close"
              @click="showSyncDataPopup = false"
            />
          </q-toolbar>
          <q-linear-progress v-if="loading" indeterminate />

          <q-separator class="separator-space" />
          <q-card-section class="q-pa-md">
            <div class="row">
              <div class="col-sm-12 col-md-12 col-lg-12">
                <q-input
                  outlined
                  dense
                  v-model="showSyncDataModel.purchase_orders"
                  :label="$t('purchase_orders')"
                />
              </div>
              <div class="col-sm-12 col-md-12 col-lg-12">
                <q-checkbox disable
                  v-model="showSyncDataModel.sync_purchase_order_bod"
                  :label="$t('sync_purchase_order')"
                />
              </div>
              <div class="col-sm-12 col-md-12 col-lg-12">
                <q-checkbox
                  v-model="showSyncDataModel.sync_receive_delivery_bod"
                  :label="$t('sync_receive_delivery')"
                />
              </div>
              <div class="col-sm-12 col-md-12 col-lg-12">
                <q-checkbox
                  v-model="
                    showSyncDataModel.sync_receive_delivery_additional_info
                  "
                  :label="$t('sync_receive_delivery_additional_info')"
                />
              </div>
            </div>
          </q-card-section>

          <q-card-actions align="right">
            <f-btn
              appearance="cancel"
              :label="$t('cancel')"
              @click="showSyncDataPopup = false"
            />
            <f-btn
              :label="$t('sync')"
              class="q-mr-sm"
              @click="confirmSyncData()"
            />
          </q-card-actions>
        </q-card>
      </q-card>
    </q-dialog>
  </template>

  <q-dialog v-model="showConfirmSyncDlg" persistent>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          {{ $t('confirm') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">On resync, you may lose PO connections.</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('done')" v-close-popup @click="syncData()" />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import { useDocumentStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { documentPOApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import helper from 'src/pages/FieldValidation/helper';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  emits: ['refreshAlreadyAddedItem'],
  mixins: [helperUtil,
    helper,
  ],
  props: {
    is_module_on: {
      type: Boolean,
      default: false,
    },
    poNumber: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      loading: ref(false),
      showSyncDataPopup: ref(false),
      showConfirmSyncDlg: ref(false),
      showSyncDataModel: ref({} as any),
    };
  },

  mounted: function () {
    this.initForm();
  },

  methods: {
    initForm() {
      this.showSyncDataModel['purchase_orders'] = this.poNumber;
      this.showSyncDataModel['sync_purchase_order_bod'] = false;
      this.showSyncDataModel['sync_receive_delivery_bod'] = false;
      this.showSyncDataModel['sync_receive_delivery_additional_info'] = false;
    },
    confirmSyncData() {
      if (
        this.record.po_multi_matched &&
        this.record.po_multi_matched.length > 0
      ) {
        this.showConfirmSyncDlg = true;
        return;
      }
      this.syncData();
    },
    async syncData() {
      if (!this.showSyncDataModel.purchase_orders) {
        notify.error('PURCHASE_ORDER_NUMBER_MANDATORY');
        return;
      }

      if (
        !this.showSyncDataModel.sync_purchase_order_bod &&
        !this.showSyncDataModel.sync_receive_delivery_bod &&
        !this.showSyncDataModel.sync_receive_delivery_additional_info
      ) {
        notify.error('SELECT_ONE_SYNC_OPTION');
        return;
      }

      try {
        this.loading = true;
        const response = await documentPOApiService.syncData(
          this.showSyncDataModel,
        );

        if (response.success === false) {
          notify.error(response.message || this.$t('po_sync_failed'));
          return;
        }
        // refresh PO data
        notify.success(response.message || this.$t('po_sync_successful'));
        this.$emit('refreshAlreadyAddedItem', this.poNumber);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
        this.showSyncDataPopup = false;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    return {
      record,
    };
  },
});
</script>

