<template>
  <q-icon
    class="hover-search-icon"
    :id="`${name}-${column}-filter`"
    style="font-size: 18px"
    :name="filterValue ? 'filter_list' : 'menu'"
    @click.stop.prevent
  >
    <q-menu @before-hide="beforeHideMenu" @before-show="beforeShowMenu">
      <div style="padding: 10px">
        <q-input
          class="width-150"
          outlined
          dense
          debounce="300"
          color="primary"
          v-model="value"
          @update:model-value="handleUpdateValue"
          label="Filter..."
        >
        </q-input>
      </div>
    </q-menu>
  </q-icon>
</template>
<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useColumnFilterStore } from 'src/store/main';

export default defineComponent({
  mixins: [],
  props: {
    name: {
      type: String,
      required: true,
      hint: 'Name of the filter',
    },
    column: {
      type: String,
      required: true,
      hint: 'Name of the column to filter',
    },
    //keep state after unmount
    persist: {
      type: Boolean,
      default: false,
      hint: 'Persist the filter value',
    },
  },
  components: {},
  computed: {
    filterValue() {
      const filterObj = this.quickFilterMap.get(this.name);
      if (filterObj && filterObj[this.column]) {
        return filterObj[this.column] as string;
      } else {
        return '';
      }
    },
  },
  mounted: function () {
    // Check if the filter is already mounted to prevent calling mounted function multiple times
    const alreadyMounted = this.componentLifeCycle.get(
      `${this.name}-filter-mounted`,
    );
    if (!alreadyMounted) {
      this.componentLifeCycle.set(`${this.name}-filter-mounted`, true);
      const filterObj = this.quickFilterMap.get(this.name);
      if (filterObj == undefined) {
        this.quickFilterMap.set(this.name, {});
      } else if (Object.keys(filterObj).length > 0) {
        this.$emit('onUpdateValue', filterObj);
      }
    }
  },
  watch: {
    quickFilterMap: {
      handler: function (newVal, oldVal) {
        const filterObj = newVal.get(this.name);
        if (!filterObj) {
          this.value = '';
          return;
        }
        this.value = Object.prototype.hasOwnProperty.call(filterObj, this.column)
          ? filterObj[this.column]
          : '';
      },
      deep: true,
    },
  },
  unmounted: function () {
    this.componentLifeCycle.delete(`${this.name}-filter-mounted`);
    if (!this.persist) {
      this.quickFilterMap.delete(this.name);
    }
  },
  methods: {
    beforeHideMenu($event: Event) {
      document
        .getElementById(`${this.name}-${this.column}-filter`)
        ?.classList.remove('always-show');
    },
    beforeShowMenu($event: Event) {
      document
        .getElementById(`${this.name}-${this.column}-filter`)
        ?.classList.add('always-show');
    },
    handleUpdateValue(value: string | number | null) {
      const filterObj = this.quickFilterMap.get(this.name);
      filterObj[this.column] = value;
      if (value == '' || value == undefined) {
        delete filterObj[this.column];
      }
      this.quickFilterMap.set(this.name, filterObj);
      this.$emit('onUpdateValue', filterObj);
    },
  },
  setup() {
    const columnFilterStore = useColumnFilterStore();
    const { quickFilterMap } = storeToRefs(columnFilterStore);
    const { resetFilters } = columnFilterStore;
    const value = ref('');
    return {
      quickFilterMap,
      resetFilters,
      componentLifeCycle: columnFilterStore.componentLifeCycle,
      value,
    };
  },
});
</script>
<style>
.always-show {
  visibility: visible !important;
}
.hover-search-icon {
  visibility: hidden;
}
th:hover .hover-search-icon {
  visibility: visible;
  cursor: pointer;
}
</style>
