<!--vbase-->
<template>
  <q-card>
    <q-toolbar class="pr-0 secondary-toolbar">
      <q-toolbar-title>
        <span class="text-white text-h6 text-weight-bold">
          {{ $t('advance_po_search') }}
        </span>
      </q-toolbar-title>

      <f-btn
        class="text-white q-mr-xs"
        flat
        round
        dense
        appearance="tertiary"
        icon="close"
        v-close-popup
      />
    </q-toolbar>

    <q-card-section>
      <div class="full-width">
        <AdvanceFilter
          @displayAdvanceFilterResults="displayAdvanceFilterResults"
          @initDashboard="initDashboard"
          :classes="'col-2 q-pa-sm'"
        />
      </div>

      <div class="full-width q-pb-sm q-pl-sm text-right">
        <PoTableColumnsSettings
          :po_columns_attr="po_columns"
          @columnsDataUpdated="loadPurchaseOrderData"
        />
      </div>
      <!-- Purchase Order Data -->

      <q-markup-table
        class="full-width height-100vh-465px"
        v-if="loading || purchaseOrderData.length == 0"
      >
        <thead v-if="!loading">
          <tr class="highlighted-back">
            <th>No Data Found</th>
          </tr>
        </thead>
        <template v-else>
          <tbody>
            <tr v-for="i in 10" :key="i">
              <td v-for="(data, index2) in 8" :key="index2">
                <q-skeleton :animation="'wave'" />
              </td>
            </tr>
          </tbody>
        </template>
      </q-markup-table>
      <DocBitsTable
        v-else
        :rows="unifiedRows"
        :columns="unifiedColumns"
        row-key="id"
        table-id="po-preview-table"
        :features="poTableFeatures"
        :loading="loading"
        no-data-label="no_data_found"
        table-class="text-uppercase"
        :table-height="'calc(100vh - 465px)'"
        @row-click="handlePoRowClick"
      >
        <template #body-cell-order_status="{ row }">
          <q-badge
            transparent
            align="middle"
            :color="statusColor(row.order_status)"
          >
            {{ row.order_status }}
          </q-badge>
        </template>
      </DocBitsTable>

      <div class="row">
        <div class="q-pa-lg center-inner">
          <div class="text-center" v-if="purchaseOrderData.length > 0">
            <q-pagination
              v-model="paginationCount"
              color="primary"
              :max="pages"
              :max-pages="6"
              boundary-links
              @click="loadData()"
            />
          </div>
        </div>
        <div class="q-mt-lg q-mr-sm">
          <f-btn
            appearance="cancel"
            :label="$t('cancel')"
            class="float-right"
            v-close-popup
          />
        </div>
      </div>

      <!-- END Purchase Order Data -->
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { po_columns } from 'src/constants';
import { usePoMatchStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { DocBitsTable } from 'src/components/Table';
import { documentPOApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import AdvanceFilter from 'src/pages/PurchaseOrders/AdvanceFilter.vue';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';
import type { UnifiedTableColumn, RowClickPayload } from 'src/components/Table';
import PoTableColumnsSettings from 'src/pages/PurchaseOrders/po-table-columns-settings.vue';

export default defineComponent({
  el: '#app',
    props: {
    po_lines: {
      type: Array,
      default: () => [],
    },
    totalRecords: {
      type: Number,
      default: 0,
    },
    po_preview_columns: [] as any,
  },
  components: { AdvanceFilter, DocBitsTable, PoTableColumnsSettings },
  emits: [
    'clearSearch',
    'addToPoItemsList',
    'proceedPoSelection',
    'displayAdvanceFilterResults',
    'searchPurchaseOrder',
  ],
  data() {
    return {
      pages: ref(0),
      po_columns: po_columns,
      purchaseOrderData: [] as dynamicObj[],
      purchaseOrderColumns: {} as dynamicObj,
    };
  },
  mounted: async function () {
    this.loading = true;
    const result = await documentPOApiService.purchaseOrdersSearch(
      this.prepareFilterRequestParams(),
    );
    this.displayAdvanceFilterResults(result);
    this.loadPurchaseOrderData();
    document.addEventListener('po_columns_updated', this.poColumnsUpdated);
    this.loading = false;
  },
  unmounted: function () {
    document.removeEventListener('po_columns_updated', this.poColumnsUpdated);
  },
  computed: {
    unifiedColumns(): UnifiedTableColumn[] {
      return Object.values(this.purchaseOrderColumns).map((col: any) => {
        const isAmount = this.checkIfColumnIsAmount(col.name);
        return {
          name: col.name,
          label: this.$t(col.translation_key),
          field: col.name,
          sortable: col.sortable !== false,
          align: (isAmount ? 'right' : 'left') as 'right' | 'left',
        };
      });
    },
    unifiedRows(): any[] {
      return this.purchaseOrderData
        .filter((line: any) => line.show)
        .map((line: any) => line.data);
    },
    poTableFeatures() {
      return {
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: false,
        columnReorder: false,
      };
    },
  },
  methods: {
    handlePoRowClick(payload: RowClickPayload) {
      this.poSelected(payload.row.purchase_order_number);
    },
    checkIfColumnIsAmount(columnName: string) {
      let isAmount = false;
      let amountColumns = [
        'position',
        'price',
        'unit_price',
        'received quantity',
        'quantity',
        'amount',
        'discount',
        'total_amount',
        'unit_price_per',
        'received_quantity',
      ];
      if (amountColumns.includes(columnName.toLowerCase())) {
        isAmount = true;
      }
      return isAmount;
    },
    async loadPurchaseOrderData() {
      this.purchaseOrderColumns = await this.getSavedColumns(po_columns);

      const sortedKeys = Object.keys(this.purchaseOrderColumns).sort((a, b) => {
        return (
          this.purchaseOrderColumns[a].order -
          this.purchaseOrderColumns[b].order
        );
      });

      const sortedObj = {} as any;
      sortedKeys.forEach((key) => {
        sortedObj[key] = this.purchaseOrderColumns[key];
      });

      this.purchaseOrderColumns = sortedObj;

      this.setPoData();

      let temp = this.totalRecords / +this.filterModel['limit'];
      this.pages = Math.ceil(temp);
    },
    poColumnsUpdated(e: any) {
      this.loadPurchaseOrderData();
    },
    async initDashboard() {
      this.loading = true;
      const result = await documentPOApiService.purchaseOrdersSearch(
        this.prepareFilterRequestParams(),
      );
      this.displayAdvanceFilterResults(result);
      this.loadPurchaseOrderData();
      this.loading = false;
    },
    setPoData() {
      try {
        this.purchaseOrderData = [];
        if (!this.po_lines || this.po_lines.length == 0) {
          return;
        }
        this.po_lines.forEach((row: any, index: any) => {
          let newRow = new Map();
          // for (let column of this.purchaseOrderColumns) {
          for (const [column, value] of Object.entries(
            this.purchaseOrderColumns,
          )) {
            newRow.set(column, row[column]);
          }
          this.purchaseOrderData.push({
            tr_data: newRow,
            data: row,
            id: row.id,
            show: true,
            connection_data: {},
          });
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    loadData() {
      this.filterModel['skip'] =
        this.filterModel['limit'] * (this.paginationCount - 1);

      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    closePreview() {
      this.$emit('clearSearch');
    },
    addToList() {
      this.$emit('addToPoItemsList');
    },
    poSelected(purchase_order_number: string) {
      this.$emit('proceedPoSelection', purchase_order_number);
    },
    displayAdvanceFilterResults(filteredPo: any) {
      this.$emit('displayAdvanceFilterResults', filteredPo);
    },
    searchPurchaseOrder() {
      return this.$emit('searchPurchaseOrder');
    },
    statusColor(status: string) {
      status = status.toLowerCase();
      return getStatusColor(status) || 'primary';
    },
  },
  setup() {
    const po_match_store = usePoMatchStore();
    const { getSavedColumns, prepareFilterRequestParams } = po_match_store;
    const { filterModel, loading } = storeToRefs(po_match_store);

    return {
      getSavedColumns,
      filterModel,
      prepareFilterRequestParams,
      paginationCount: ref(1),
      loading,
    };
  },
});
</script>

