/**
 * Shared pure helpers for the Purchase Order tables.
 *
 * Used by both:
 * - src/pages/PurchaseOrders/PurchaseOrder.vue
 * - src/pages/PurchaseOrders/ServerSideMatching/PurchaseOrder.vue
 *
 * Only stateless utilities live here — anything that needs component state
 * (this.tableRows, this.record, etc.) stays on the component.
 */

import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';

/**
 * Returns the formatted column value if available, otherwise the raw value.
 */
export function colValue(row: any, col_name: string): string {
  let value = row[col_name];
  if (Object.prototype.hasOwnProperty.call(row, col_name + '_formatted_value')) {
    value = row[col_name + '_formatted_value'];
  }
  return value as string;
}

/**
 * Column sorting guard — the connection_status column is never sortable.
 */
export function allowedColumnSorting(column: { name: string }): boolean {
  return column.name !== 'connection_status';
}

/**
 * Resolves a PO status to a Quasar color token, with a primary fallback.
 */
export function statusColor(status: string): string {
  return getStatusColor(status.toLowerCase()) || 'primary';
}

/**
 * Date fields that appear on PO line rows and how they should be formatted.
 * - `true`  → date-only (yyyy-mm-dd)
 * - `false` → full datetime
 */
export const PO_DATE_FIELDS: ReadonlyArray<readonly [string, boolean]> = [
  ['promised_delivery_date', true],
  ['requested_ship_date', true],
  ['received_date_time', false],
] as const;

/**
 * Formats known date fields on a PO row in place using the supplied formatter.
 * Missing fields are skipped. The formatter is injected so this stays pure
 * and independent of the component's mixin.
 */
export function formatPoDateFields(
  newRow: Record<string, any>,
  formatDateAccordingToPreference: (value: any, dateOnly?: boolean) => string
): void {
  for (const [field, isDateOnly] of PO_DATE_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(newRow, field)) {
      newRow[field] = formatDateAccordingToPreference(newRow[field], isDateOnly);
    }
  }
}
