<template>

  <div class="full-width dashboard-list-area q-pt-md">
      <ColumnFilterBadges class="q-mb-sm" name="ShipmentColumnFilter" @onUpdateValue="(prop: dynamicObj[]) => {filterValue = {...prop}}"/>
      <q-table v-if="rows && rows.length > 0"
          class="sticky-header table_height resizable compact-table-tr q-table--compact"
          :no-data-label="$t('no_record_found')"
          :rows="filteredTableRow"
          :columns="columns"
          ref="el"
          row-key="name"
          :rows-per-page-options="[0]"
          :id="tableId"
      >
      <template v-slot:header="props">
              <q-tr :props="props" >
                <q-th
                  v-for="col in props.cols"
                  :key="col.name"
                  :props="props"
                >
                  <span v-if="col.label == 'position'" class="float-right">{{ col.label }}</span>
                  <span v-else
                  :class="col.is_bold || col.name === po_quantity_column ? 'text-weight-bolder font-size-14 secondary-c-text' : ''"
                
                  >{{ col.label }}</span>
                  <ColumnFilter v-if="col.label" name="ShipmentColumnFilter" :column="col.name" @onUpdateValue="(prop: dynamicObj[]) => {filterValue = {...prop}}"/>
                </q-th>
              </q-tr>
      </template>
      <template v-slot:body="props">
        <q-tr :props="props" :data-id='props.key' :class="(props.rowIndex % 2 == 0 ? '' : 'alternative-row')" >
          <template v-for="(col) in props.cols" :key="col.name" :props="props">
            <q-td v-if="col.label" >
              <span :class="checkIfColumnIsAmount(col.name, AMOUNT_COLUMNS) ? 'float-right' : ''">
                {{ props.row[col.name] }}
              </span>
            </q-td>
            <q-td v-else >
              <div class="display-flex q-py-xs">
                <div style="width: 300px ">

                  <q-slider v-model="props.row[col.name].already_delivered" readonly draggable="false" dense :max="100" :inner-max="props.row[col.name].bar_value" 
                      color="success" inner-track-color="primary" track-size="8px" thumb-size="0px"/>
                </div>
                <span class="q-px-sm text-success">
                  {{ props.row[col.name].bar_value }} %
                </span>
                <span class="q-px-sm" :class="props.row[col.name].delivered_on_time ? 'text-success' : 'text-error'">
                  {{ props.row[col.name].promised_delivery_date}}
                </span>
                <span class="q-px-sm" v-if="!props.row[col.name].delivered_on_time" :class="props.row[col.name].delivered_on_time ? 'text-success' : 'text-error'">
                  {{ props.row[col.name].no_of_days_late + ' day(s) late' }}
                </span>
              </div>
            </q-td>
          </template>
        </q-tr>
      </template>
      </q-table>
      <q-markup-table class='full-width' v-else>
        <thead>
          <tr >
            <th> {{ $t('no_record_found') }}</th>
          </tr>
        </thead>

      </q-markup-table>
  </div>
  <Loader />
</template>

<script lang="ts">

import { debounce } from 'quasar'
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { dateFormates } from 'src/constants';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import { useResizeObserver } from '@vueuse/core';
import { type dynamicObj, $ } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import docTablesUtil from 'src/utils/docTablesUtil';
import resizableGridUtil from 'src/utils/resizableGridUtil';
import ColumnFilter from '../Dashboard/ColumnFilter.vue';
import ColumnFilterBadges from '../Dashboard/ColumnFilterBadges.vue';
import { AMOUNT_COLUMNS } from 'src/pages/PurchaseOrders/constants.js';
import { usePoMatchStore, useSettingStore, useDocumentStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  props: {
    purchaseOrderNumber: {
      type: String,
      default: ''
    },
    poItems: {
      type: Object,
      default: ()=>({})
    }
  },
  watch: {
    purchaseOrderNumber: {
      handler: function (newVal: any, oldVal: any) {
        if(newVal && newVal != oldVal) {
          this.prepareTableRows(newVal);
        }
      },
    },
  },
  data() {
    return {
      rows: ref([] as any),
      columns: ref([] as any),
      startY: 0,
      isResizing: false,
      AMOUNT_COLUMNS,
      filterValue: ref({}),
      tableId: 'receive-delivery-lines-table',
  };
},
mixins: [ helperMixin, dateUtils, docTablesUtil, helperUtil, resizableGridUtil ],
components: { Loader, ColumnFilter, ColumnFilterBadges },
updated(){
    let setting = this.user_settings.RECEIVE_DELIVERY_LINES_TABLE_SETTING
    let height = 200;
    if(setting){
        setting = JSON.parse(setting);
        height = setting.height as number
    }
    const element = document.getElementById(this.tableId);
    if(element) {
      if(height < 200){
        height = 200;
      }
      element.style.height = height + 'px';
    }
  },
mounted() {
  this.init();
  document.addEventListener('reload_received_delivery_lines', this.reloadData);
},
unmounted() {
    document.removeEventListener('reload_received_delivery_lines', this.reloadData);
    this.destoryAndRest(this.tableId);
},
computed: {
    filteredTableRow(){
      return this.filterByObject(this.rows, this.filterValue)
    }
},
methods: {
  async init() {
    this.prepareTableColumns();
    await this.$nextTick();
    this.initTableColumnResize(this.tableId);
  },
  calculateTableHeight () {

      let setting = this.user_settings.RECEIVE_DELIVERY_LINES_TABLE_SETTING;
        if(setting){
          setting = JSON.parse(setting);
          if(setting.hasOwnProperty('height')) {
            this.tableHeight = setting.height;
          }
        }
        if (this.rows.length > 0 && (this.rows.length < 3 || this.tableHeight < 10)) {
          this.tableHeight = 200;
        }
  },

  prepareTableColumns() {
      this.columns = [];
      this.columns.push(
        {
            name: 'item_id',
            label: this.$t('item_id'),
            field: 'item_id',
            align: 'left',
            sortable: true,
            headerStyle: 'width: 100px',
        },
        {
            name: 'delivery_number',
            label: this.$t('delivery_number'),
            field: 'delivery_number',
            align: 'left',
            sortable: true,
            headerStyle: 'width: 150px',
        },
        {
            name: 'shipped_quantity',
            label: this.$t('shipped_quantity'),
            field: 'shipped_quantity',
            align: 'left',
            sortable: true,
            headerStyle: 'width: 150px',
        },
        {
            name: 'invoiced_quantity',
            label: this.$t('invoiced_quantity'),
            field: 'invoiced_quantity',
            align: 'left',
            sortable: true,
            headerStyle: 'width: 150px',
        },
        {
            name: 'invoice_open_quantity',
            label: this.$t('invoice_open_quantity'),
            field: 'invoice_open_quantity',
            align: 'left',
            sortable: true,
            headerStyle: 'width: 150px',
        },
        {
            name: 'chart_status',
            label: '',
            field: 'chart_status',
            align: 'left',
            sortable: false,
        },
          
      );
  },
  reloadData(e: any) {
    if(!this.purchaseOrderNumber) {
      return;
    }
    this.prepareTableRows(this.purchaseOrderNumber);
  },
  prepareTableRows(poNumber: string) {

    this.rows = [];

    for(let row of this.poItems[poNumber]) {

      let alreadyDeliveredPercent = this.getQuantityPercent(row.shipped_quantity, row.invoiced_quantity);

      let deliveredNow = this.getPOMatchedQuentyPercentatge(row.id, row.shipped_quantity);

      let barValue = alreadyDeliveredPercent + deliveredNow;

      const receivedDateTime = this.formatDateWithPattern(row.received_date_time, dateFormates.date_only);
      const promisedDeliveryDate = this.formatDateWithPattern(row.promised_delivery_date, dateFormates.date_only);

      const isdeliveredOnTime = this.compareDates(receivedDateTime, promisedDeliveryDate);

      const newRow = {
        'item_id': row.item_id,
        'delivery_number': row.delivery_number,
        'shipped_quantity': row.shipped_quantity,
        'invoiced_quantity': row.invoiced_quantity,
        'invoice_open_quantity': row.invoice_open_quantity,
        'chart_status': {
          'received_date_time': receivedDateTime,
          'promised_delivery_date': promisedDeliveryDate,
          'bar_value': barValue,
          'already_delivered': alreadyDeliveredPercent,
          'delivered_on_time': isdeliveredOnTime,
          'no_of_days_late': isdeliveredOnTime ? this.dateDifferenceInDays(receivedDateTime, promisedDeliveryDate) : 0,
        },
      };

      this.rows.push(newRow);
    }
    this.calculateTableHeight();

    // Reinitialize column resize after data loads
    this.$nextTick(() => {
      this.resetAndReInitColumnResize(this.tableId);
    });
  },
  getQuantityPercent(shippedQuantity: string, invoicedQuantity: string) {

    if(!shippedQuantity || !invoicedQuantity || Number(shippedQuantity) == 0 || Number(invoicedQuantity) == 0) {
      return 0;
    }
    let percentage = ( Number(invoicedQuantity) / Number(shippedQuantity) ) * 100;

    return Number(percentage.toFixed());
  },
  getPOMatchedQuentyPercentatge(poId: string, shippedQuantity: string) {

    // verify Ifrecors is matched
    const {found, invoiceQuantity} = this.verifyIfPoIsMatched(poId);

    if(!found) {
      return 0;
    }

    return this.getQuantityPercent(shippedQuantity, invoiceQuantity);
  },

  verifyIfPoIsMatched(poLineId: string): any {

      let found = false;
      let invoiceQuantity = 0;

      if(!this.record.po_multi_matched || this.record.po_multi_matched.entries().length == 0) {
        return {found, invoiceQuantity};
      }

      mainLoop:
      for (let [index, record] of this.record.po_multi_matched.entries()) {

        if(record.hasOwnProperty('po_line_id')) {
          if(record.po_line_id == poLineId) {
            found = true;
            invoiceQuantity = record.quantity
            break mainLoop;
          }

        } else if(record.hasOwnProperty('sub_lines')) {
          for (let [sub_index, sub_line] of record.sub_lines.entries()) {
            if(sub_line.po_line_id == poLineId) {
              found = true;
              invoiceQuantity = sub_line.quantity
              break mainLoop;
            }
          }
        }
      }

      return {found, invoiceQuantity};
  },
  startResize(e: any) {
    this.startY = e.clientY;
    this.isResizing = true;
    document.addEventListener('mousemove', this.resize);
    document.addEventListener('mouseup', this.stopResize);
  },
  resize(e: any) {
    if (this.isResizing) {
      const dy = e.clientY - this.startY;
      this.tableHeight += dy;
    }
  },
  stopResize() {
    this.isResizing = false;
    document.removeEventListener('mousemove', this.resize);
    document.removeEventListener('mouseup', this.stopResize);
  }
},
setup() {
  const settings_store = useSettingStore();
  const { user_settings } = storeToRefs(settings_store);
  const { setUserPreferences } = settings_store;

  const po_match_store = usePoMatchStore();
  const { PODataObj, po_quantity_column } = storeToRefs(po_match_store);
  const el = ref(null)
  const doc_store = useDocumentStore();
  const { record } = storeToRefs(doc_store);
  let tableHeight = 200

  useResizeObserver(el, debounce((entries) => {
      const entry = entries[0]
      //if RECEIVE_DELIVERY_LINES_TABLE_SETTING is set and if it is set and the height is the same, return
      if(user_settings.value.RECEIVE_DELIVERY_LINES_TABLE_SETTING){
        const tableSetting = JSON.parse(user_settings.value.RECEIVE_DELIVERY_LINES_TABLE_SETTING);
        //if the height is below 10px diff, return
        if(Math.abs(tableSetting.height - entry.contentRect.height) < 10) return;
      }
      if(entry.contentRect.width < 20 || entry.contentRect.height < 20) return;
      setUserPreferences('RECEIVE_DELIVERY_LINES_TABLE_SETTING',JSON.stringify(entry.contentRect));
  },1000))
 
  return {
    record,
    el,
    PODataObj,
    po_quantity_column,
    user_settings,
    tableHeight
  };
}
});
</script>

<style scoped lang="scss">
    .resizable {
      resize: vertical;
      overflow: auto;
    }
</style>

<style scoped>
  body.body--light .resizable {
    border: 1px solid rgba(0, 0, 0, 0.12)
  }
  body.body--dark .resizable {
    border: 1px solid rgba(255, 255, 255, 0.28);
  }
</style>