<template>
  <div class="row">
    <div :class="classes">
      <q-input
        outlined
        v-model="filterModel['q']"
        dense
        :label="$t('keyword')"
        @keyup="onKeyup"
      />
    </div>

    <div :class="classes">
      <q-select
        ref="supplierSelect"
        dense
        outlined
        use-input
        emit-value
        map-options
        tabindex="0"
        input-debounce="1000"
        hide-dropdown-icon
        v-model="filterModel['supplier']"
        :options="supplier_options"
        @filter="updateSearchValue"
        @update:model-value="selectValueToSearch"
        :loading="loading_supplier_options"
        :label="$t('supplier')"
        @keyup="onKeyupChange"
      >
        <template v-if="search_value" v-slot:option="scope">
          <q-item v-bind="scope.itemProps">
            <q-item-section>
              <q-item-label>
                <span v-html="styleSupplerOptions(scope.opt.label)"></span
              ></q-item-label>
            </q-item-section>
          </q-item>
        </template>
        <template v-slot:no-option>
          <q-item>
            <q-item-section>
              {{ $t('no_data_found') }}
            </q-item-section>
          </q-item>
        </template>
        <template v-slot:append>
          <q-icon
            name="close"
            @click.stop.prevent="clearSupplierSearch"
            v-if="filterModel['supplier'] !== ''"
            class="cursor-pointer"
          />
        </template>
      </q-select>
    </div>

    <div :class="classes">
      <q-select
        dense
        clearable
        outlined
        emit-value
        map-options
        v-model="filterModel['status']"
        :options="statusOptions"
        :label="$t('status')"
        @update:model-value="applyFilters"
      />
    </div>

    <div :class="classes">
      <q-select
        dense
        clearable
        outlined
        emit-value
        map-options
        v-model="filterModel['order_status']"
        :options="statusOptions"
        :label="$t('order_status')"
        @update:model-value="applyFilters"
      />
    </div>

    <div :class="classes">
      <q-input
        outlined
        dense
        v-model="filterModel['after_date']"
        readonly
        :label="$t('after_date')"
      >
        <template v-slot:append>
          <q-icon name="event" class="cursor-pointer">
            <q-popup-proxy
              cover
              transition-show="scale"
              transition-hide="scale"
            >
              <q-date v-model="filterModel['after_date']" mask="YYYY-MM-DD">
                <div class="row items-center justify-end">
                  <q-btn v-close-popup label="Close" color="primary" flat />
                </div>
              </q-date>
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-input>
    </div>

    <div :class="classes">
      <q-input
        outlined
        dense
        v-model="filterModel['before_date']"
        readonly
        :label="$t('before_date')"
      >
        <template v-slot:append>
          <q-icon name="event" class="cursor-pointer">
            <q-popup-proxy
              cover
              transition-show="scale"
              transition-hide="scale"
            >
              <q-date v-model="filterModel['before_date']" mask="YYYY-MM-DD">
                <div class="row items-center justify-end">
                  <q-btn v-close-popup label="Close" color="primary" flat />
                </div>
              </q-date>
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-input>
    </div>

    <div :class="classes">
      <q-input
        outlined
        v-model="filterModel['min_amount']"
        dense
        :label="$t('min_order_amount')"
        type="number"
        @keyup="onKeyup"
      />
    </div>

    <div :class="classes">
      <q-input
        outlined
        v-model="filterModel['max_amount']"
        dense
        :label="$t('max_order_amount')"
        type="number"
        @keyup="onKeyup"
      />
    </div>

    <div :class="classes">
      <q-select
        dense
        outlined
        emit-value
        map-options
        v-model="filterModel['sort_by']"
        :options="sortByStatus"
        :label="$t('sort_by')"
        @update:model-value="applyFilters"
      />
    </div>

    <div :class="classes">
      <q-select
        dense
        outlined
        emit-value
        map-options
        v-model="filterModel['order']"
        :options="orderList"
        :label="$t('sort_direction')"
        @update:model-value="applyFilters"
      />
    </div>
    <div :class="classes">
      <q-select
        dense
        outlined
        v-model="filterModel['limit']"
        :options="pagination_options"
        @update:model-value="applyFilters"
        :label="$t('no_of_items')"
      />
    </div>
    <div
      v-for="(key, index) in enabledColumnsToSearch"
      :key="key"
      :class="classes"
    >
      <q-input
        outlined
        v-model="filterModel[key]"
        dense
        :label="$t(key)"
        type="text"
        @keyup="onKeyup"
      >
        <template v-slot:append>
          <q-btn
            @click="removeColumnFromSearch(key, index)"
            round
            dense
            flat
            icon="close"
            class="cursor-pointer"
          />
        </template>
      </q-input>
    </div>
    <div :class="classes">
      <q-btn
        :disabled="enabledColumnsToSearch.length == columnsToSearch.length"
        :label="$t('more')"
        color="primary"
      >
        <q-menu ref="moreOptionsEl">
          <q-list>
            <template v-for="key in columnsToSearch" :key="key">
              <q-item
                v-if="!enabledColumnsToSearch.includes(key)"
                clickable
                @click="pushColumnsToSearch(key)"
              >
                <q-item-section>
                  {{ $t(key) }}
                </q-item-section>
              </q-item>
            </template>
          </q-list>
        </q-menu>
        <q-icon dense flat name="add" />
      </q-btn>
    </div>
    <div class="row full-width justify-end q-mb-sm">
      <f-btn
        appearance="secondary"
        class="q-mr-sm"
        :label="$t('clear')"
        @click="clearFilter()"
      />
      <f-btn class="q-mr-sm" :label="$t('apply')" @click="clickApplyFilter" />
    </div>
  </div>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { date } from 'quasar';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { usePoMatchStore } from 'src/store/main';
import { isEmptyString } from 'src/utils/general';
import stringUtil from 'src/utils/string';
import { purchaseOrderService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { PO_STATUSES } from 'src/pages/PurchaseOrders/constants.js';
export default defineComponent({
  mixins: [helperMixin, stringUtil],
  emits: ['displayAdvanceFilterResults', 'initDashboard'],
  props: {
    classes: {
      type: String,
      default: 'col-6 q-pa-sm',
    },
  },
  components: { Loader },
  data() {
    return {
      columnsToSearch: ['delivery_number', 'packing_slip_number', 'item_id'],
      orderList: [] as any,
      sortByStatus: [] as any,
      statusOptions: [] as any,
      PO_STATUSES,
      search_value: ref(''),
      enterValue: ref(''),
      loading_supplier_options: ref(false),
      supplierSelect: null,
    };
  },
  watch: {
    search_value(newValue: string) {
      if (newValue === '') {
        this.removeFocusFromQSelect();
      }
    },
    enterValue(enterVal: string) {
      if (enterVal === '') {
        this.removeFocusFromQSelect();
      }
    },
  },
  mounted() {
    this.initOrder();
    this.initStatus();
    this.initSortByStatus();
    document.addEventListener('apply_filters', this.applyFilterEvent);
  },
  unmounted() {
    document.removeEventListener('apply_filters', this.applyFilterEvent);
  },

  methods: {
    removeColumnFromSearch(key: string, index: number) {
      this.enabledColumnsToSearch.splice(index, 1);
      delete this.filterModel[key];
    },
    pushColumnsToSearch(key: string) {
      if (!this.enabledColumnsToSearch.includes(key)) {
        this.enabledColumnsToSearch.push(key);
        Object.assign(this.filterModel, { [key]: '' });
      }
      this.moreOptionsEl.hide();
    },
    clickApplyFilter() {
      this.filterModel['skip'] = 0;
      this.applyFilters(true);
    },
    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.filterModel['skip'] = 0;
        this.search_value = this.filterModel['supplier'];
        this.applyFilters();
      }
    },
    applyFilterEvent(e: any) {
      this.applyFilters();
    },

    applyFilters(showPreview = false) {
      try {
        if (this.po_preview) {
          this.$emit('initDashboard');
        } else {
          if (showPreview == true) {
            this.po_preview = true;
          }
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },

    initOrder() {
      this.orderList = [
        {
          label: this.$t('sort_asc'),
          value: 'asc',
        },
        {
          label: this.$t('sort_desc'),
          value: 'desc',
        },
      ];
    },
    initStatus() {
      this.statusOptions = [];
      for (const [key, item] of Object.entries(this.PO_STATUSES)) {
        const status = item as any;
        this.statusOptions.push({
          label: this.$t(status.label),
          value: status.value,
        });
      }
    },
    initSortByStatus() {
      this.sortByStatus = [
        {
          label: this.$t('purchase_order_number'),
          value: 'purchase_order_number',
        },
        {
          label: this.$t('line_number'),
          value: 'line_number',
        },
        {
          label: this.$t('sub_line_number'),
          value: 'sub_line_number',
        },
        {
          label: this.$t('supplier_id'),
          value: 'supplier_id',
        },
        {
          label: this.$t('supplier_name'),
          value: 'supplier_name',
        },
        {
          label: this.$t('item_id'),
          value: 'item_id',
        },
        {
          label: this.$t('supplier_id'),
          value: 'supplier_id',
        },
        {
          label: this.$t('supplier_item_id'),
          value: 'supplier_item_id',
        },
        {
          label: this.$t('order_total_amount'),
          value: 'order_total_amount',
        },
        {
          label: this.$t('order_date'),
          value: 'order_date',
        },
        {
          label: this.$t('requested_shipment_date'),
          value: 'requested_shipment_date',
        },
        {
          label: this.$t('status'),
          value: 'status',
        },
        {
          label: this.$t('delivery_number'),
          value: 'delivery_number',
        },
        {
          label: this.$t('packing_slip_number'),
          value: 'packing_slip_number',
        },
        {
          label: this.$t('delivery_line_number'),
          value: 'delivery_line_number',
        },
        {
          label: this.$t('quantity'),
          value: 'quantity',
        },
        {
          label: this.$t('shipped_quantity'),
          value: 'shipped_quantity',
        },
        {
          label: this.$t('open_quantity'),
          value: 'open_quantity',
        },
        {
          label: this.$t('received_quantity'),
          value: 'received_quantity',
        },
      ];
    },

    // Supplier Auto Complete
    clearSupplierSearch() {
      this.search_value = '';
      this.filterModel['supplier'] = '';
      this.enterValue = '';
      this.applyFilters();
    },
    removeFocusFromQSelect() {
      if (this.$refs.supplierSelect) {
        (this.$refs.supplierSelect as any).blur();
      }
    },
    onKeyupChange(event: any) {
      if (event.key == 'Enter') {
        this.filterModel['supplier'] = this.enterValue;
        this.filterModel['skip'] = 0;
        this.applyFilters();
      }
    },

    async updateSearchValue(value: string, update: any, abort: any) {
      if (isEmptyString(value) || value.length < 2) {
        abort();
        return;
      } else {
        try {
          this.loading_supplier_options = true;
          let options = [] as dynamicObj[];
          const suppliers = (await this.getSupplierFromServer(
            value,
          )) as dynamicObj;
          for (const [key, value] of Object.entries(suppliers)) {
            options.push({
              value: value,
              label: value,
            });
          }

          this.enterValue = value;

          update(() => {
            this.supplier_options = options;
          });
        } catch (err: any) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          if (msg) {
            notify.error(msg);
          }
        } finally {
          this.loading_supplier_options = false;
        }
      }
    },

    async getSupplierFromServer(keyword: string) {
      try {
        let items = [] as dynamicObj[];
        const params = {
          keyword,
        };
        const response = await purchaseOrderService.getSuppliers(params);
        if (response.success == false) {
          throw response;
        }
        items = response.data;
        return items;
      } catch (err) {
        throw err;
      }
    },

    selectValueToSearch(value: any) {
      try {
        this.filterModel['supplier'] = value;
        this.filterModel['skip'] = 0;
        this.applyFilters();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    styleSupplerOptions(text: string) {
      const regex = new RegExp(this.supplier_search, 'gi');
      const label = text.replace(regex, (match) => `<strong>${match}</strong>`);
      return label;
    },

    // END Supplier Auto Complete
    clearFilter() {
      this.initFilterModel();
      this.clearSupplierSearch();
    },
  },
  setup() {
    const moreOptionsEl = ref();
    const po_match_store = usePoMatchStore();
    const { initFilterModel, prepareFilterRequestParams } = po_match_store;
    const {
      filterModel,
      supplier_options,
      supplier_search,
      loading,
      po_preview,
      enabledColumnsToSearch,
    } = storeToRefs(po_match_store);

    return {
      prepareFilterRequestParams,
      loading,
      initFilterModel,
      filterModel,
      moreOptionsEl,
      pagination_options: ref(['10', '25', '50']),
      supplier_options,
      supplier_search,
      po_preview,
      enabledColumnsToSearch,
      // loading_supplier_options: ref(false),
    };
  },
});
</script>
<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}
</style>
