<template>
  <q-toolbar class="text-white secondary-toolbar">
    <q-toolbar-title>
      <span class="text-weight-bold">{{ $t('keyboard_shortcuts') }}</span>
    </q-toolbar-title>
    <q-btn flat round dense icon="close" v-close-popup />
  </q-toolbar>

  <q-card-section class="full-height scrolle-y">
    <q-markup-table class="dashboard-table-style" flat>
      <thead>
        <tr class="highlighted-back">
          <th class="text-left" style="font-weight: bold">
            {{ $t('action') }}
          </th>
          <th class="text-left max-width-100">{{ $t('keyboard_shortcut') }}</th>
        </tr>
      </thead>
      <tbody>
        <template v-for="shortcut in keyboardShortcuts" :key="shortcut.action">
          <tr>
            <td class="text-left full-width ellipsify">
              {{ shortcut.action }}
            </td>
            <td class="text-left">
              <span v-if="shortcut.onlyAlt && !showAlt(shortcut)">
                <q-icon size="40px" class="black_to_white alt-mg">
                  <img :src="'/images/alt.svg'"/>
                </q-icon>
              </span>
              <span
                class="q-px-sm"
                v-for="(key, index) in getShortcutFields(shortcut)"
                :key="index"
              >
                <kbd v-if="isKey(key)">{{ trimKey(key) }} </kbd>
                <span v-else>{{ key }} </span>
                <span v-if="showAlt(shortcut) && isTextCtrl(key)">
                  /
                  <q-icon size="40px" class="black_to_white">
                    <img :src="'/images/alt.svg'"/>
                  </q-icon>
                </span>
              </span>
            </td>
          </tr>
        </template>
      </tbody>
    </q-markup-table>
  </q-card-section>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
export default defineComponent({
  methods: {
    getShortcutFields(shortcut: any) {
       
      return shortcut.shortcut.split(' ');
    },
    trimKey(key: string) {
      return key.replace('[', '').replace(']', '').replace(/_/g, ' ');
    },
    isKey(key: string) {
      return key.startsWith('[') && key.endsWith(']');
    },
    showAlt(shortcut: any) {
      if (shortcut.showAlt) {
        return true;
      }
    },
    isTextCtrl(key: string) {
      if (key.replace('[', '').replace(']', '') == 'CTRL') {
        return true;
      }
    },
  },
  data() {
    return {
      keyboardShortcuts: [
        {
          action: 'Move between items (Generic)',
          shortcut: '[TAB]',
        },
        {
          action: 'Move between items (specific to po Items)',
          shortcut: '[CTRL] + [M]',
        },
        {
          action: 'To Select or click a item',
          shortcut: '[ENTER]',
        },
        {
          action: 'Open Help',
          shortcut: '[CTRL] + [H]',
        },
        {
          action: 'Check keyboard shortcut',
          shortcut: '[CTRL] + [K]',
        },
        {
          action: 'Enable/Disable PO traning mode',
          shortcut: '[CTRL] + [D]',
        },
        {
          action: 'Auto PO match',
          shortcut: '[CTRL] + [A]',
        },
        {
          action: 'Save PO',
          shortcut: '[CTRL] + [S]',
        },
        {
          action: 'Reject',
          shortcut: ' + [R]',
          onlyAlt: true,
        },
        {
          action: 'Export PO',
          shortcut: '[CTRL] + [E]',
        },
        {
          action: 'Search PO',
          shortcut: '[CTRL] + [F]',
        },
        {
          action: 'Selecting first row of PO items',
          shortcut: '[CTRL] + [P]',
        },
        {
          action: 'Selecting first row of Line items',
          shortcut: '[CTRL] + [L]',
        },
        {
          action: 'Selecting and remove selected rows of Line items',
          shortcut: '[CTRL] + [Left_Click]',
        },
        {
          action: 'Select row to start mapping on line items',
          shortcut: '[CTRL] + [C]',
          showAlt: true,
        },
        {
          action: 'Map selected PO row to selected Line Item',
          shortcut: '[CTRL] + [V]',
          showAlt: true,
        },
        {
          action: 'Select All PO Match',
          shortcut: '[CTRL] + [SHIFT] + [Left_Click]',
        },
      ],
    };
  },
});
</script>

