<!--vbase-->
<template>
  <q-tooltip v-if="isVisible" class="quantity-tooltip-wrapper" @before-show="onBeforeShow">
    <div class="quantity-tooltip">
      <div class="tooltip-row">
        <span class="tooltip-label">{{ $t('document_quantity') }}:</span>
        <span class="tooltip-value">{{ displayDocumentQuantity }}</span>
      </div>
      <div class="tooltip-row">
        <span class="tooltip-label">{{ $t('matched_quantity') }}:</span>
        <span class="tooltip-value">{{ matchedQuantity }}</span>
      </div>
      <div class="tooltip-row">
        <span class="tooltip-label">{{ $t('remaining_quantity') }}:</span>
        <span class="tooltip-value">{{ remainingQuantity }}</span>
      </div>
    </div>
  </q-tooltip>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { usePoMatchStore, useAmountFormatStore, useDocumentStore } from 'src/store/main';

export default defineComponent({
  name: 'QuantityTooltip',
  props: {
    lineId: {
      type: String,
      required: true
    },
    documentQuantity: {
      type: [String, Number],
      required: true
    },
    documentQuantityFormated: {
      type: String,
      required: true
    },
    poConnectedItems: {
      type: Object,
      required: true
    },
    PODataObj: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      matchedQuantity: '0.00' as string,
      remainingQuantity: '0.00' as string,
      adjustedDocumentQuantity: '0.00' as string
    };
  },
  computed: {
    connectionData(): any {
      return this.poConnectedItems[this.lineId] || null;
    },
    isVisible(): boolean {
      return !!this.connectionData;
    },
    hasSubLines(): boolean {
      return !!(this.connectionData?.sub_lines && Array.isArray(this.connectionData.sub_lines));
    },
    poItem(): any {
      if (!this.connectionData) return null;
      const poLineId = this.hasSubLines
        ? this.connectionData.sub_lines[0]?.po_line_id
        : this.connectionData.po_line_id;
      return this.PODataObj[poLineId];
    },
    isMilUnit(): boolean {
      return this.poItem?.unit_code === 'MIL';
    },
    displayDocumentQuantity(): string {
      return this.isMilUnit ? this.adjustedDocumentQuantity : this.documentQuantityFormated;
    }
  },
  mounted() {
    this.calculateAdjustedDocumentQuantity();
    this.calculateMatchedQuantity();
    this.calculateRemainingQuantity();
  },
  methods: {
    async onBeforeShow() {
      await this.formatQuantities();
    },
    calculateAdjustedDocumentQuantity() {
      if (!this.connectionData) return;

      let docQty = Number(this.documentQuantity) || 0;
      if (this.isMilUnit) {
        docQty = docQty / 1000;
      }
      this.adjustedDocumentQuantity = docQty.toFixed(2);
    },
    calculateMatchedQuantity() {
      if (!this.connectionData) return;

      let matchedQty = 0;
      // Case 1: Single table line with multiple PO lines (has sub_lines)
      if (this.hasSubLines) {
        this.connectionData.sub_lines.forEach((subLine: any) => {
          matchedQty += Number(this.getPoQuantity(this.PODataObj[subLine.po_line_id])) || 0;
        });
      }
      // Case 2: Multiple table lines with single PO line (has table_lines)
      // Case 3: Single match (has po_line_id directly)
      else {
        matchedQty = Number(this.getPoQuantity(this.PODataObj[this.connectionData.po_line_id])) || 0;
      }
      this.matchedQuantity = matchedQty.toFixed(2);
    },
    calculateRemainingQuantity() {
      const docQty = Number(this.adjustedDocumentQuantity) || 0;
      const matchedQty = Number(this.matchedQuantity) || 0;
      this.remainingQuantity = (docQty - matchedQty).toFixed(2);
    },
    async formatQuantities() {
      const values = [
        { key: this.adjustedDocumentQuantity, value: this.adjustedDocumentQuantity },
        { key: this.matchedQuantity, value: this.matchedQuantity },
        { key: this.remainingQuantity, value: this.remainingQuantity }
      ];

      const formatted_values = await this.amount_format_store.formatMultiValues(
        values,
        'en_US',
        this.doc_store.amount_format_locale
      );

      this.adjustedDocumentQuantity = this.amount_format_store.searchValueByKey(this.adjustedDocumentQuantity, formatted_values);
      this.matchedQuantity = this.amount_format_store.searchValueByKey(this.matchedQuantity, formatted_values);
      this.remainingQuantity = this.amount_format_store.searchValueByKey(this.remainingQuantity, formatted_values);
    }
  },
  setup() {
    const po_match_store = usePoMatchStore();
    const amount_format_store = useAmountFormatStore();
    const doc_store = useDocumentStore();
    const { getPoQuantity } = po_match_store;

    return {
      getPoQuantity,
      amount_format_store,
      doc_store
    };
  }
});
</script>

